def missing_numbers(arr, low, high):
  p1 = 0  # pointer for arr
  p2 = low  # pointer for virtual arr2
  res = []

  while p1 < len(arr) and p2 <= high:
    if arr[p1] < p2:
      p1 += 1
    elif arr[p1] == p2:
      p1 += 1
      p2 += 1
    else:
      res.append(p2)
      p2 += 1

  if p2 <= high:
    res.extend(range(p2, high + 1))
  return res

