  let p1 = 0; // pointer for arr
  let p2 = low; // pointer for virtual arr2
  const res = [];

  while (p1 < arr.length && p2 <= high) {
    if (arr[p1] < p2) {
      p1++;
    } else if (arr[p1] === p2) {
      p1++;
      p2++;
    } else {
      res.push(p2);
      p2++;
    }
  }

  if (p2 <= high) {
    for (let i = p2; i <= high; i++) {
      res.push(i);
    }
  }
  return res;
}

